parameters.query:
DECLARE @cliente NVARCHAR(100) = '{{ $json.cliente }}';
DECLARE @periodo NVARCHAR(20) = '{{ $json.periodo }}';
DECLARE @sin_asignar BIT = CASE WHEN '{{ $json.sin_asignar }}' = 'true' THEN 1 ELSE 0 END;

DECLARE @desde DATE;
DECLARE @hasta DATE;

IF @periodo = 'semana'
BEGIN
    SET @desde = DATEADD(DAY, 1 - DATEPART(WEEKDAY, GETDATE()), CAST(GETDATE() AS DATE));
    SET @hasta = DATEADD(DAY, 7, @desde);
END
ELSE
BEGIN
    SET @desde = CAST(GETDATE() AS DATE);
    SET @hasta = DATEADD(DAY, 1, @desde);
END;

SELECT TOP 50
    cdbNumeroPedido AS Pedido,
    cdbCliente AS CodigoCliente,
    cdbNombreCliente AS Cliente,
    cdbFechaCarga AS FechaCarga,
    cdbOriPoblacion AS Origen,
    cdbDesPoblacion AS Destino,
    cdbMatriculaVehiculo AS Matricula,
    cdbNombreConductor AS Conductor,
    cdbMercancia AS Mercancia,
    cdbImporte AS Importe
FROM [T_DIANIA].[dbo].[tdbPedidos]
WHERE cdbFechaCarga >= @desde
  AND cdbFechaCarga < @hasta
  AND (
        @cliente = ''
        OR cdbNombreCliente LIKE '%' + @cliente + '%'
      )
  AND (
        @sin_asignar = 0
        OR cdbMatriculaVehiculo IS NULL
      )
ORDER BY cdbFechaCarga DESC;

