const rows = $input.all().map(i => i.json);

if (rows.length === 0) {
  return [{
    json: {
      text: "No he encontrado pedidos con esos filtros."
    }
  }];
}

let texto = `He encontrado ${rows.length} pedido(s):\n\n`;

for (const r of rows) {
  texto += `📦 Pedido ${r.Pedido}\n`;
  texto += `Cliente: ${r.Cliente}\n`;
  texto += `Fecha carga: ${r.FechaCarga}\n`;
  texto += `Ruta: ${r.Origen || ""} → ${r.Destino || ""}\n`;
  texto += `Matrícula: ${r.Matricula || "sin asignar"}\n`;
  texto += `Conductor: ${r.Conductor || "sin asignar"}\n`;

  if (r.Importe !== null && r.Importe !== undefined) {
    texto += `Importe: ${r.Importe} €\n`;
  }

  texto += `\n`;
}

return [{ json: { text: texto } }];

